                    st=[(i,j)]; comp=set()
                    while st:
                        a,b=st.pop()
                        if (a,b) in comp: continue
                        comp.add((a,b)); seen[a][b]=True
                        for da,db in DIRS:
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and di[x][y]==color and (x,y) not in comp: st.append((x,y))
                    if len(comp)<12: continue
                    if not all(sum(1 for a,b in comp for da,db in DIRS if (a+da,b+db) in comp)==2 for a,b in comp): continue
                    inner={(a+s,b+t_) for a,b in comp for s,t_ in DIRS if 0<=a+s<H and 0<=b+t_<W and di[a+s][b+t_]==bg}
                    for a,b in inner: out[a][b]=fillc
    return out
